        "        print(f\"💰 Жалпы StarCoin: {starcoin}\")\n",
        "\n",
        "    else:\n",
        "        print(\"❌ Қате жауап.\")\n",
        "        print(f\"💡 Дұрыс жауап: {task['answer']}\")\n",
        "\n",
        "print(\"\\n==========================================\")\n",
        "print(\"🏆 ОЙЫН НӘТИЖЕСІ\")\n",
        "print(\"==========================================\")\n",
        "\n",
        "print(f\"✅ Дұрыс жауап: {correct} / {len(tasks)}\")\n",
        "print(f\"⭐ Жиналған StarCoin: {starcoin}\")\n",
        "\n",
        "# ------------------------------------------\n",
        "# ДЕҢГЕЙ\n",
        "# ------------------------------------------\n",
        "\n",
        "if starcoin >= 90:\n",
        "    level = \"🏆 MASTER\"\n",
        "elif starcoin >= 70:\n",
        "    level = \"🥇 EXPERT\"\n",
        "elif starcoin >= 50:\n",
        "    level = \"🥈 ADVANCED\"\n",
        "elif starcoin >= 30:\n",
        "    level = \"🥉 BEGINNER\"\n",
        "else:\n",
        "    level = \"🌱 STARTER\"\n",
        "\n",
        "print(f\"🎮 Ойын деңгейі: {level}\")\n",
        "\n",
        "print(\"==========================================\")\n",
        "print(\"🤖 AI ҰСТАЗ:\")\n",
        "print(\"Әр дұрыс жауап — жаңа мүмкіндік!\")\n",
