        "tasks = [\n",
        "    {\n",
        "        \"question\": \"Python-да экранға мәлімет шығару функциясы?\",\n",
        "        \"answer\": \"print\"\n",
        "    },\n",
        "    {\n",
        "        \"question\": \"5 + 7 нәтижесі?\",\n",
        "        \"answer\": \"12\"\n",
        "    },\n",
        "    {\n",
        "        \"question\": \"Шартты тексеру операторы?\",\n",
        "        \"answer\": \"if\"\n",
        "    },\n",
        "    {\n",
        "        \"question\": \"range(5) неше сан береді?\",\n",
        "        \"answer\": \"5\"\n",
        "    },\n",
        "    {\n",
        "        \"question\": \"1 byte неше bit?\",\n",
        "        \"answer\": \"8\"\n",
