        "\n",
        "score = 0\n",
        "starcoin = 0\n",
        "\n",
        "print(\"==========================================\")\n",
        "print(\"🤖 AI ИНФОРМАТИКА ҰСТАЗЫ\")\n",
        "print(\"18-Миссия\")\n",
        "print(\"📊 ОҚУШЫ ДЕҢГЕЙІН АНЫҚТАУ\")\n",
        "print(\"==========================================\")\n",
        "\n",
        "for i, task in enumerate(tasks, 1):\n",
        "\n",
