        "    print(task[\"question\"])\n",
        "\n",
        "    user_answer = input(\"👉 Жауабыңыз: \").strip().lower()\n",
        "\n",
        "    if task[\"answer\"].lower() in user_answer:\n",
        "        print(\"✅ Дұрыс!\")\n",
        "        score += 1\n",
        "        starcoin += 10\n",
        "        print(\"⭐ +10 StarCoin\")\n",
        "    else:\n",
        "        print(\"❌ Қате.\")\n",
        "        print(f\"💡 Дұрыс жауап: {task['answer']}\")\n",
        "\n",
        "# ------------------------------------------\n",
        "# НӘТИЖЕ\n",
        "# ------------------------------------------\n",
        "\n",
        "percentage = score / len(tasks) * 100\n",
        "\n",
        "print(\"\\n==========================================\")\n",
        "print(\"🏆 ОҚУШЫ НӘТИЖЕСІ\")\n",
        "print(\"==========================================\")\n",
        "\n",
        "print(f\"✅ Дұрыс жауап: {score} / {len(tasks)}\")\n",
        "print(f\"📊 Нәтиже: {percentage:.1f}%\")\n",
        "print(f\"⭐ StarCoin: {starcoin}\")\n",
        "\n",
        "# ------------------------------------------\n",
        "# ДЕҢГЕЙДІ АНЫҚТАУ\n",
        "# ------------------------------------------\n",
        "\n",
        "if percentage >= 90:\n",
        "    level = \"🏆 MASTER\"\n",
        "    advice = \"Сіз информатика тақырыптарын өте жақсы меңгердіңіз!\"\n",
        "\n",
        "elif percentage >= 75:\n",
