        "students = []\n",
        "\n",
        "print(\"==========================================\")\n",
        "print(\"🤖 AI ИНФОРМАТИКА ҰСТАЗЫ\")\n",
        "print(\"📊 ОҚУШЫ НӘТИЖЕЛЕРІН СҰРЫПТАУ\")\n",
        "print(\"==========================================\")\n",
        "\n",
        "number_of_students = int(input(\"👥 Қанша оқушы енгізесіз? \"))\n",
        "\n",
        "for i in range(number_of_students):\n",
        "\n",
        "    print(f\"\\n👨‍🎓 {i + 1}-оқушы\")\n",
        "\n",
        "    name = input(\"Аты-жөні: \")\n",
        "    correct = int(input(\"Дұрыс жауап саны (0-10): \"))\n",
        "\n",
        "    percentage = correct / 10 * 100\n",
        "    starcoin = correct * 10\n",
        "\n",
        "    if percentage >= 90:\n",
        "        level = \"MASTER\"\n",
        "    elif percentage >= 75:\n",
        "        level = \"EXPERT\"\n",
        "    elif percentage >= 60:\n",
        "        level = \"ADVANCED\"\n",
        "    elif percentage >= 40:\n",
        "        level = \"BEGINNER\"\n",
        "    else:\n",
        "        level = \"STARTER\"\n",
        "\n",
        "    students.append({\n",
        "        \"Оқушы\": name,\n",
        "        \"Дұрыс\": correct,\n",
        "        \"Нәтиже\": percentage,\n",
        "        \"StarCoin\": starcoin,\n",
        "        \"Деңгей\": level\n",
        "    })\n",
        "\n",
        "# Нәтижені жоғарыдан төменге сұрыптау\n",
        "students.sort(\n",
        "    key=lambda student: student[\"Нәтиже\"],\n",
        "    reverse=True\n",
        ")\n",
        "\n",
        "print(\"\\n==========================================\")\n",
        "print(\"🏆 ОҚУШЫЛАР РЕЙТИНГІ\")\n",
        "print(\"==========================================\")\n",
        "\n",
        "for place, student in enumerate(students, 1):\n",
        "\n",
        "    if place == 1:\n",
        "        medal = \"🥇\"\n",
        "    elif place == 2:\n",
        "        medal = \"🥈\"\n",
        "    elif place == 3:\n",
        "        medal = \"🥉\"\n",
        "    else:\n",
        "        medal = \"⭐\"\n",
        "\n",
        "    print(\n",
        "        f\"{medal} {place}-орын | \"\n",
        "        f\"{student['Оқушы']} | \"\n",
        "        f\"{student['Дұрыс']}/10 | \"\n",
        "        f\"{student['Нәтиже']:.1f}% | \"\n",
        "        f\"⭐ {student['StarCoin']} | \"\n",
        "        f\"{student['Деңгей']}\"\n",
        "    )\n",
        "\n",
        "print(\"==========================================\")\n",
        "\n",
        "print(\"\\n🌟 ЕҢ ЖОҒАРЫ НӘТИЖЕ:\")\n",
