        "import pandas as pd\n",
        "\n",
        "print(\"==========================================\")\n",
        "print(\"🤖 AI ИНФОРМАТИКА ҰСТАЗЫ\")\n",
        "print(\"👥 СЫНЫП НӘТИЖЕЛЕРІ\")\n",
        "print(\"==========================================\")\n",
        "\n",
        "class_results = []\n",
        "\n",
        "number_of_students = int(\n",
        "    input(\"👥 Қанша оқушы нәтиже тапсырады? \")\n",
        ")\n",
        "\n",
        "for student_number in range(1, number_of_students + 1):\n",
        "\n",
        "    print(\"\\n------------------------------------------\")\n",
        "    print(f\"👨‍🎓 {student_number}-оқушы\")\n",
        "    print(\"------------------------------------------\")\n",
        "\n",
        "    student_name = input(\"Аты-жөні: \")\n",
        "\n",
        "    print(\"\\n📚 Тараулар:\")\n",
        "\n",
        "    for number, chapter in all_chapters.items():\n",
        "        print(f\"{number}️⃣ {chapter}\")\n",
        "\n",
        "    choice = int(input(\"📌 Тарау нөмірі (1-12): \"))\n",
        "\n",
        "    if choice not in all_chapters:\n",
        "        print(\"❌ Қате тарау.\")\n",
        "        continue\n",
        "\n",
        "    chapter_name = all_chapters[choice]\n",
        "\n",
        "    tasks = chapter_tasks[choice]\n",
        "\n",
        "    correct_count = 0\n",
        "\n",
        "    for number, task in enumerate(tasks, 1):\n",
        "\n",
        "        task_type, question, correct_answer = task\n",
        "\n",
        "        print(f\"\\n📌 {number}-тапсырма\")\n",
        "        print(f\"📝 {question}\")\n",
        "\n",
        "        user_answer = input(\"👉 Жауабыңыз: \").strip().lower()\n",
        "\n",
        "        if correct_answer.lower() in user_answer:\n",
        "            print(\"✅ Дұрыс!\")\n",
        "            correct_count += 1\n",
        "        else:\n",
        "            print(\"❌ Қате.\")\n",
        "            print(\"💡 Дұрыс жауап:\", correct_answer)\n",
        "\n",
        "    percentage = correct_count / 12 * 100\n",
        "    starcoin = correct_count * 10\n",
        "\n",
        "    if percentage >= 90:\n",
        "        level = \"MASTER\"\n",
        "    elif percentage >= 75:\n",
        "        level = \"EXPERT\"\n",
        "    elif percentage >= 60:\n",
        "        level = \"ADVANCED\"\n",
        "    elif percentage >= 40:\n",
        "        level = \"BEGINNER\"\n",
        "    else:\n",
        "        level = \"STARTER\"\n",
        "\n",
        "    class_results.append({\n",
        "        \"Оқушы\": student_name,\n",
        "        \"Тарау\": chapter_name,\n",
        "        \"Дұрыс\": correct_count,\n",
        "        \"Нәтиже (%)\": round(percentage, 1),\n",
        "        \"StarCoin\": starcoin,\n",
        "        \"Деңгей\": level\n",
        "    })\n",
        "\n",
        "    print(f\"\\n✅ {student_name} нәтижесі сақталды!\")\n",
        "\n",
        "# ==========================================\n",
        "# СЫНЫПТЫҢ ЖАЛПЫ НӘТИЖЕСІ\n",
        "# ==========================================\n",
        "\n",
        "print(\"\\n==========================================\")\n",
        "print(\"📊 СЫНЫПТЫҢ ЖАЛПЫ НӘТИЖЕСІ\")\n",
        "print(\"==========================================\")\n",
        "\n",
        "df_class = pd.DataFrame(class_results)\n",
        "\n",
        "if len(df_class) > 0:\n",
        "\n",
        "    # Нәтиже бойынша жоғарыдан төмен сұрыптау\n",
        "    df_class = df_class.sort_values(\n",
        "        by=\"Нәтиже (%)\",\n",
        "        ascending=False\n",
        "    )\n",
        "\n",
        "    display(df_class)\n",
        "\n",
        "    # Excel сақтау\n",
        "    df_class.to_excel(\n",
        "        \"AI_Информатика_Ұстазы_Сынып_нәтижесі.xlsx\",\n",
        "        index=False\n",
        "    )\n",
        "\n",
        "    print(\"\\n🏆 ЕҢ ЖОҒАРЫ НӘТИЖЕ:\")\n",
