        "# ==========================================\n",
        "# 🤖 AI ИНФОРМАТИКА ҰСТАЗЫ\n",
        "# 40-Миссия — ОҚУШЫНЫҢ ЖЕКЕ ПРОФИЛІ\n",
        "# ==========================================\n",
        "\n",
        "print(\"==========================================\")\n",
        "print(\"🤖 AI ИНФОРМАТИКА ҰСТАЗЫ\")\n",
        "print(\"👤 ОҚУШЫНЫҢ ЖЕКЕ ПРОФИЛІ\")\n",
        "print(\"==========================================\")\n",
        "\n",
        "if \"df_class\" not in globals():\n",
        "\n",
        "    print(\"❌ Оқушы нәтижесі табылмады.\")\n",
        "    print(\"📌 Алдымен 32-Миссияны іске қосыңыз.\")\n",
        "\n",
        "else:\n",
        "\n",
        "    student_names = list(df_class[\"Оқушы\"].unique())\n",
        "\n",
        "    print(\"📋 ОҚУШЫЛАР:\")\n",
        "\n",
        "    for i, name in enumerate(student_names, 1):\n",
        "        print(f\"{i}. {name}\")\n",
        "\n",
        "    student_number = int(\n",
        "        input(\"\\n👨‍🎓 Оқушы нөмірін таңдаңыз: \")\n",
        "    )\n",
        "\n",
        "    if 1 <= student_number <= len(student_names):\n",
        "\n",
        "        student_name = student_names[student_number - 1]\n",
        "\n",
        "        student_data = df_class[\n",
        "            df_class[\"Оқушы\"] == student_name\n",
        "        ].copy()\n",
        "\n",
        "        # Жалпы нәтиже\n",
        "        total_correct = student_data[\"Дұрыс\"].sum()\n",
        "        total_tasks = len(student_data) * 12\n",
        "\n",
        "        if total_tasks > 0:\n",
        "            progress = total_correct / total_tasks * 100\n",
        "        else:\n",
        "            progress = 0\n",
        "\n",
        "        # StarCoin\n",
        "        starcoin = int(total_correct * 10)\n",
        "\n",
        "        # Деңгей\n",
        "        if starcoin >= 100:\n",
        "            level = \"MASTER\"\n",
        "            badge = \"👑\"\n",
        "        elif starcoin >= 80:\n",
        "            level = \"EXPERT\"\n",
        "            badge = \"💎\"\n",
        "        elif starcoin >= 60:\n",
        "            level = \"ADVANCED\"\n",
        "            badge = \"🏆\"\n",
        "        elif starcoin >= 40:\n",
        "            level = \"BEGINNER\"\n",
        "            badge = \"⭐\"\n",
        "        else:\n",
        "            level = \"STARTER\"\n",
        "            badge = \"🌱\"\n",
        "\n",
        "        # Ең әлсіз тарау\n",
        "        weakest = student_data.loc[\n",
        "            student_data[\"Нәтиже (%)\"].idxmin()\n",
        "        ]\n",
        "\n",
        "        # Ең жақсы тарау\n",
        "        best = student_data.loc[\n",
        "            student_data[\"Нәтиже (%)\"].idxmax()\n",
        "        ]\n",
        "\n",
        "        # ------------------------------------------\n",
        "        # ЖЕКЕ ПРОФИЛЬ\n",
        "        # ------------------------------------------\n",
        "\n",
        "        print(\"\\n==========================================\")\n",
        "        print(\"👤 МЕНІҢ ПРОФИЛІМ\")\n",
        "        print(\"==========================================\")\n",
        "\n",
        "        print(f\"👨‍🎓 Оқушы: {student_name}\")\n",
        "        print(f\"⭐ StarCoin: {starcoin}\")\n",
        "        print(f\"{badge} Деңгей: {level}\")\n",
        "        print(f\"📊 Жалпы прогресс: {progress:.1f}%\")\n",
        "\n",
        "        print(\"\\n==========================================\")\n",
        "        print(\"📚 ТАРАУЛАР НӘТИЖЕСІ\")\n",
        "        print(\"==========================================\")\n",
        "\n",
        "        for _, row in student_data.iterrows():\n",
        "\n",
        "            result = row[\"Нәтиже (%)\"]\n",
        "\n",
        "            if result >= 75:\n",
        "                icon = \"🟢\"\n",
        "            elif result >= 50:\n",
        "                icon = \"🟡\"\n",
        "            else:\n",
        "                icon = \"🔴\"\n",
        "\n",
        "            print(\n",
        "                f\"{icon} {row['Тарау']} — \"\n",
        "                f\"{result}%\"\n",
        "            )\n",
        "\n",
        "        print(\"\\n==========================================\")\n",
        "        print(\"🏆 ЖЕТІСТІКТЕР\")\n",
        "        print(\"==========================================\")\n",
        "\n",
        "        print(\n",
        "            f\"🟢 Ең жақсы тарау: \"\n",
        "            f\"{best['Тарау']} — {best['Нәтиже (%)']}%\"\n",
        "        )\n",
        "\n",
        "        print(\n",
        "            f\"🔴 Әлсіз тарау: \"\n",
        "            f\"{weakest['Тарау']} — {weakest['Нәтиже (%)']}%\"\n",
        "        )\n",
        "\n",
        "        print(\"\\n==========================================\")\n",
        "        print(\"🤖 AI ҰСТАЗДЫҢ ҰСЫНЫСЫ\")\n",
        "        print(\"==========================================\")\n",
        "\n",
        "        if weakest[\"Нәтиже (%)\"] < 40:\n",
        "\n",
        "            print(\"📚 Бұл тақырыпты қайта оқу қажет.\")\n",
        "            print(\"✏️ Алдымен жеңіл тапсырмалардан бастаңыз.\")\n",
        "            print(\"🔄 Түзету сабағын орындаңыз.\")\n",
        "\n",
        "        elif weakest[\"Нәтиже (%)\"] < 60:\n",
        "\n",
        "            print(\"🟠 Бұл тақырыпты қайталау ұсынылады.\")\n",
        "            print(\"✏️ Қосымша тапсырмалар орындаңыз.\")\n",
        "\n",
        "        elif weakest[\"Нәтиже (%)\"] < 75:\n",
