        "    print(f\"👥 Оқушылар саны: {total_students}\")\n",
        "    print(f\"📊 Орташа нәтиже: {average_result:.1f}%\")\n",
        "    print(f\"✅ Барлық дұрыс жауап: {total_correct}\")\n",
        "\n",
        "    print(\"\\n==========================================\")\n",
        "    print(\"🏆 ҮЗДІК ОҚУШЫ\")\n",
        "    print(\"==========================================\")\n",
        "\n",
        "    best_student = df_class.loc[\n",
        "        df_class[\"Нәтиже (%)\"].idxmax()\n",
        "    ]\n",
        "\n",
        "    print(\n",
        "        f\"🥇 {best_student['Оқушы']} — \"\n",
        "        f\"{best_student['Нәтиже (%)']}%\"\n",
        "    )\n",
        "\n",
        "    print(\"\\n==========================================\")\n",
        "    print(\"🔴 ҚОСЫМША ЖҰМЫС ҚАЖЕТ ОҚУШЫ\")\n",
        "    print(\"==========================================\")\n",
        "\n",
        "    weak_student = df_class.loc[\n",
        "        df_class[\"Нәтиже (%)\"].idxmin()\n",
        "    ]\n",
        "\n",
        "    print(\n",
        "        f\"📚 {weak_student['Оқушы']} — \"\n",
        "        f\"{weak_student['Нәтиже (%)']}%\"\n",
        "    )\n",
        "\n",
        "    print(\"\\n==========================================\")\n",
        "    print(\"💡 AI ҰСЫНЫСЫ\")\n",
        "    print(\"==========================================\")\n",
        "\n",
        "    if average_result >= 80:\n",
        "        print(\"🌟 Сыныптың нәтижесі өте жақсы!\")\n",
        "        print(\"🚀 Күрделі тапсырмалар беруге болады.\")\n",
        "\n",
        "    elif average_result >= 60:\n",
        "        print(\"👍 Сыныптың нәтижесі жақсы.\")\n",
        "        print(\"📚 Кейбір тақырыптарды қайталау ұсынылады.\")\n",
        "\n",
        "    elif average_result >= 40:\n",
        "        print(\"🟠 Сыныпқа қосымша жаттығулар қажет.\")\n",
        "        print(\"🔄 Әлсіз тақырыптарды қайталау керек.\")\n",
        "\n",
        "    else:\n",
        "        print(\"🔴 Сыныптың нәтижесі төмен.\")\n",
        "        print(\"📖 Негізгі теорияны қайта оқыту ұсынылады.\")\n",
        "\n",
        "    print(\"\\n==========================================\")\n",
        "    print(\"💾 ЕСЕПТІ EXCEL ФАЙЛЫНА САҚТАУ\")\n",
        "    print(\"==========================================\")\n",
        "\n",
