        "\n",
        "print(\"==========================================\")\n",
        "print(\"🤖 AI ИНФОРМАТИКА ҰСТАЗЫ\")\n",
        "print(\"🏅 ОҚУШЫЛАРДЫ ДЕҢГЕЙ БОЙЫНША ТОПТАСТЫРУ\")\n",
        "print(\"==========================================\")\n",
        "\n",
        "if \"df_class\" not in globals():\n",
        "\n",
        "    print(\"❌ Сынып нәтижесі табылмады.\")\n",
        "    print(\"📌 Алдымен 32-Миссияны іске қосыңыз.\")\n",
        "\n",
        "else:\n",
        "\n",
        "    # Әр оқушының жалпы нәтижесін есептеу\n",
        "    student_summary = (\n",
        "        df_class\n",
        "        .groupby(\"Оқушы\")\n",
        "        .agg(\n",
