        "        if percent >= 90:\n",
        "            return \"MASTER 👑\"\n",
        "\n",
        "        elif percent >= 75:\n",
        "            return \"EXPERT 💎\"\n",
        "\n",
        "        elif percent >= 60:\n",
        "            return \"ADVANCED 🏆\"\n",
        "\n",
        "        elif percent >= 40:\n",
        "            return \"BEGINNER ⭐\"\n",
        "\n",
        "        else:\n",
        "            return \"STARTER 🌱\"\n",
        "\n",
        "    student_summary[\"Деңгей\"] = (\n",
        "        student_summary[\"Нәтиже (%)\"]\n",
        "        .apply(get_level)\n",
        "    )\n",
