        "# ==========================================\n",
        "# 🤖 AI ИНФОРМАТИКА ҰСТАЗЫ\n",
        "# 51-Миссия — AI БЕЙІМДЕЛГЕН ТАПСЫРМА\n",
        "# ==========================================\n",
        "\n",
        "print(\"==========================================\")\n",
        "print(\"🤖 AI ИНФОРМАТИКА ҰСТАЗЫ\")\n",
        "print(\"🧠 AI БЕЙІМДЕЛГЕН ОҚЫТУ\")\n",
        "print(\"==========================================\")\n",
        "\n",
        "if \"students\" not in globals() or len(students) == 0:\n",
        "\n",
        "    print(\"❌ Оқушы нәтижесі табылмады.\")\n",
        "    print(\"📌 Алдымен 32-Миссияны орындаңыз.\")\n",
        "\n",
        "else:\n",
        "\n",
        "    print(\"\\n👥 ОҚУШЫЛАР:\")\n",
        "\n",
        "    for i, student in enumerate(students, 1):\n",
        "        print(\n",
        "            f\"{i}️⃣ {student['Оқушы']} — \"\n",
        "            f\"{student['Нәтиже']:.1f}% — \"\n",
        "            f\"{student['Деңгей']}\"\n",
        "        )\n",
        "\n",
        "    choice = int(input(\"\\n📌 Оқушы нөмірін таңдаңыз: \"))\n",
        "\n",
        "    if choice < 1 or choice > len(students):\n",
        "\n",
        "        print(\"❌ Қате нөмір.\")\n",
        "\n",
        "    else:\n",
        "\n",
        "        student = students[choice - 1]\n",
        "\n",
        "        name = student[\"Оқушы\"]\n",
        "        result = student[\"Нәтиже\"]\n",
        "\n",
        "        # Нәтижеге қарай тапсырма деңгейін анықтау\n",
        "\n",
        "        if result < 40:\n",
        "            difficulty = \"ЖЕҢІЛ\"\n",
        "        elif result < 75:\n",
        "            difficulty = \"ОРТАША\"\n",
        "        else:\n",
        "            difficulty = \"КҮРДЕЛІ\"\n",
        "\n",
        "        # Тапсырмалар\n",
        "\n",
        "        tasks = {\n",
        "\n",
        "            \"ЖЕҢІЛ\": {\n",
        "                \"question\": \"Python-да экранға ақпарат шығару үшін қандай функция қолданылады?\",\n",
        "                \"answer\": \"print\"\n",
        "            },\n",
        "\n",
        "            \"ОРТАША\": {\n",
        "                \"question\": \"x = 10. Егер x > 5 болса, шарттың нәтижесі қандай?\",\n",
        "                \"answer\": \"true\"\n",
        "            },\n",
        "\n",
        "            \"КҮРДЕЛІ\": {\n",
        "                \"question\": \"numbers = [10, 20, 30]. numbers[1] мәні қандай?\",\n",
        "                \"answer\": \"20\"\n",
        "            }\n",
        "        }\n",
        "\n",
        "        task = tasks[difficulty]\n",
        "\n",
        "        print(\"\\n==========================================\")\n",
        "        print(f\"👨‍🎓 Оқушы: {name}\")\n",
        "        print(f\"📈 Нәтиже: {result:.1f}%\")\n",
        "        print(f\"🎯 AI анықтаған деңгей: {difficulty}\")\n",
        "        print(\"==========================================\")\n",
        "\n",
        "        print(\"\\n📝 СІЗГЕ АРНАЛҒАН ТАПСЫРМА:\")\n",
        "        print(\"------------------------------------------\")\n",
        "        print(task[\"question\"])\n",
        "\n",
        "        user_answer = input(\"\\n👉 Жауабыңыз: \").strip().lower()\n",
        "\n",
        "        if task[\"answer\"].lower() in user_answer:\n",
        "\n",
        "            print(\"\\n✅ ДҰРЫС!\")\n",
        "            print(\"🌟 AI сіздің жауабыңызды дұрыс деп таныды.\")\n",
        "            print(\"⭐ +10 StarCoin\")\n",
        "\n",
        "            student[\"StarCoin\"] += 10\n",
        "\n",
        "        else:\n",
        "\n",
        "            print(\"\\n❌ ҚАТЕ.\")\n",
        "\n",
        "            print(\"\\n🤖 AI ТҮСІНДІРМЕСІ:\")\n",
        "            print(\"💡 Дұрыс жауап:\", task[\"answer\"])\n",
