        "        total_starcoin = ayan[\"StarCoin\"].sum()\n",
        "\n",
        "        best = ayan.loc[ayan[\"Нәтиже (%)\"].idxmax()]\n",
        "        weakest = ayan.loc[ayan[\"Нәтиже (%)\"].idxmin()]\n",
        "\n",
        "        print(\"\\n📊 ЖАЛПЫ ПРОГРЕСС\")\n",
        "        print(\"------------------------------------------\")\n",
        "        print(f\"👨‍🎓 Оқушы: Аян\")\n",
        "        print(f\"📚 Орындалған тарау: {len(ayan)}\")\n",
        "        print(f\"📈 Орташа нәтиже: {average:.1f}%\")\n",
        "        print(f\"⭐ Жалпы StarCoin: {total_starcoin}\")\n",
        "\n",
        "        print(\"\\n🏆 ЕҢ ЖАҚСЫ НӘТИЖЕ:\")\n",
        "        print(f\"🟢 {best['Тарау']} — {best['Нәтиже (%)']:.1f}%\")\n",
        "\n",
        "        print(\"\\n📚 ҚАЙТАЛАУ КЕРЕК ТАРАУ:\")\n",
        "        print(f\"🔴 {weakest['Тарау']} — {weakest['Нәтиже (%)']:.1f}%\")\n",
        "\n",
