        "\n",
        "print(\"==========================================\")\n",
        "print(\"🤖 AI ИНФОРМАТИКА ҰСТАЗЫ\")\n",
        "print(\"🔍 ҚАТЕНІ ТАЛДАУ МОДУЛІ\")\n",
        "print(\"==========================================\")\n",
        "\n",
