        "# ==========================================\n",
        "# ⭐ 63-Миссия — ПРОГРЕСС ГРАФИГІ\n",
        "# ==========================================\n",
        "\n",
        "import pandas as pd\n",
        "import matplotlib.pyplot as plt\n",
        "\n",
        "print(\"==========================================\")\n",
        "print(\"🤖 AI ИНФОРМАТИКА ҰСТАЗЫ\")\n",
        "print(\"📈 АЯННЫҢ ПРОГРЕСС ГРАФИГІ\")\n",
        "print(\"==========================================\")\n",
        "\n",
        "df = pd.DataFrame(learning_results)\n",
        "\n",
        "ayan = df[df[\"Оқушы\"].astype(str).str.lower() == \"аян\"].copy()\n",
        "\n",
        "if len(ayan) == 0:\n",
        "    print(\"❌ Аянның нәтижесі табылмады.\")\n",
        "else:\n",
        "    ayan = ayan.reset_index(drop=True)\n",
        "\n",
        "    ayan[\"Әрекет\"] = range(1, len(ayan) + 1)\n",
        "\n",
        "    plt.figure(figsize=(8, 5))\n",
        "\n",
        "    plt.plot(\n",
        "        ayan[\"Әрекет\"],\n",
        "        ayan[\"Нәтиже (%)\"],\n",
        "        marker=\"o\",\n",
        "        linewidth=2\n",
        "    )\n",
        "\n",
        "    for x, y in zip(ayan[\"Әрекет\"], ayan[\"Нәтиже (%)\"]):\n",
        "        plt.text(x, y + 3, f\"{y:.1f}%\", ha=\"center\")\n",
        "\n",
        "    plt.title(\"Аянның оқу прогресі\")\n",
        "    plt.xlabel(\"Тапсырма нәтижесі\")\n",
        "    plt.ylabel(\"Нәтиже (%)\")\n",
        "    plt.ylim(0, 110)\n",
        "    plt.xticks(ayan[\"Әрекет\"])\n",
        "    plt.grid(True, linestyle=\"--\", alpha=0.5)\n",
        "\n",
        "    plt.show()\n",
        "\n",
        "    print(\"\\n📊 ПРОГРЕСС:\")\n",
        "    print(\"------------------------------------------\")\n",
        "    print(f\"Бастапқы нәтиже: {ayan.iloc[0]['Нәтиже (%)']:.1f}%\")\n",
        "    print(f\"Соңғы нәтиже: {ayan.iloc[-1]['Нәтиже (%)']:.1f}%\")\n",
        "\n",
