        "# ==========================================\n",
        "# ⭐ 64-Миссия — AI КЕЛЕСІ ТАРАУДЫ ҰСЫНУ\n",
        "# ==========================================\n",
        "\n",
        "import pandas as pd\n",
        "\n",
        "print(\"==========================================\")\n",
        "print(\"🤖 AI ИНФОРМАТИКА ҰСТАЗЫ\")\n",
        "print(\"📚 КЕЛЕСІ ТАРАУДЫ ҰСЫНУ\")\n",
        "print(\"==========================================\")\n",
        "\n",
        "df = pd.DataFrame(learning_results)\n",
        "\n",
        "ayan = df[df[\"Оқушы\"].astype(str).str.lower() == \"аян\"].copy()\n",
        "\n",
        "chapters = [\n",
        "    \"Компьютер жүйелері және желілер\",\n",
        "    \"Ақпаратты ұсыну және өлшем бірліктері\",\n",
        "    \"Python бағдарламалау негіздері\",\n",
        "    \"Алгоритм және блок-схема\",\n",
        "    \"Python if және else\",\n",
        "    \"Python while циклі\",\n",
        "    \"Python тізімдері (list)\",\n",
        "    \"Python функциялары\",\n",
        "    \"Python мәтіндері (str)\",\n",
        "    \"Python сөздіктері (dict)\",\n",
        "    \"Python файлдармен жұмыс\",\n",
        "    \"Python for циклі және range()\"\n",
        "]\n",
        "\n",
        "if len(ayan) == 0:\n",
