        "    display(ayan)\n",
        "\n",
        "    best = ayan.loc[ayan[\"Нәтиже (%)\"].idxmax()]\n",
        "    weakest = ayan.loc[ayan[\"Нәтиже (%)\"].idxmin()]\n",
        "    average = ayan[\"Нәтиже (%)\"].mean()\n",
        "\n",
        "    print(\"\\n🏆 ЕҢ ЖАҚСЫ ТАРАУ:\")\n",
        "    print(f\"🟢 {best['Тарау']}\")\n",
        "    print(f\"📈 Нәтиже: {best['Нәтиже (%)']:.1f}%\")\n",
        "\n",
        "    print(\"\\n🔴 ЕҢ ӘЛСІЗ ТАРАУ:\")\n",
        "    print(f\"📚 {weakest['Тарау']}\")\n",
        "    print(f\"📉 Нәтиже: {weakest['Нәтиже (%)']:.1f}%\")\n",
        "\n",
        "    print(\"\\n📊 ОРТАША НӘТИЖЕ:\")\n",
        "    print(f\"{average:.1f}%\")\n",
        "\n",
        "    print(\"\\n🤖 AI ҚОРЫТЫНДЫСЫ:\")\n",
        "\n",
        "    if best[\"Нәтиже (%)\"] >= 90:\n",
        "        print(\"🌟 Ең жақсы тарау өте жақсы меңгерілген.\")\n",
        "    else:\n",
        "        print(\"👍 Ең жақсы тарауда негізгі білім қалыптасқан.\")\n",
        "\n",
