        "    print(\"❌ Аянның нәтижесі табылмады.\")\n",
        "\n",
        "else:\n",
        "    weakest = ayan.loc[ayan[\"Нәтиже (%)\"].idxmin()]\n",
        "\n",
        "    chapter = weakest[\"Тарау\"]\n",
        "    score = weakest[\"Нәтиже (%)\"]\n",
        "\n",
