        "    display(df)\n",
        "\n",
        "    print(\"\\n📊 ЖАЛПЫ КӨРСЕТКІШТЕР\")\n",
        "    print(\"------------------------------------------\")\n",
        "\n",
        "    print(f\"👥 Нәтиже саны: {len(df)}\")\n",
        "    print(f\"📈 Орташа нәтиже: {df['Нәтиже (%)'].mean():.1f}%\")\n",
        "    print(f\"⭐ Барлық StarCoin: {df['StarCoin'].sum()}\")\n",
        "\n",
        "    best_student = df.loc[df[\"Нәтиже (%)\"].idxmax()]\n",
        "    weakest_student = df.loc[df[\"Нәтиже (%)\"].idxmin()]\n",
        "\n",
        "    print(\"\\n🏆 ЕҢ ЖОҒАРЫ НӘТИЖЕ\")\n",
        "    print(\"------------------------------------------\")\n",
        "    print(f\"👨‍🎓 {best_student['Оқушы']}\")\n",
        "    print(f\"📚 {best_student['Тарау']}\")\n",
        "    print(f\"📈 {best_student['Нәтиже (%)']:.1f}%\")\n",
        "\n",
        "    print(\"\\n🔴 ҚОСЫМША КӨМЕК ҚАЖЕТ\")\n",
        "    print(\"------------------------------------------\")\n",
        "    print(f\"👨‍🎓 {weakest_student['Оқушы']}\")\n",
        "    print(f\"📚 {weakest_student['Тарау']}\")\n",
        "    print(f\"📉 {weakest_student['Нәтиже (%)']:.1f}%\")\n",
        "\n",
        "    print(\"\\n📊 ДЕҢГЕЙЛЕР\")\n",
        "    print(\"------------------------------------------\")\n",
        "\n",
        "    level_counts = df[\"Деңгей\"].value_counts()\n",
        "\n",
        "    for level, count in level_counts.items():\n",
        "        print(f\"🏅 {level}: {count} оқушы\")\n",
        "\n",
        "    print(\"\\n🤖 AI МҰҒАЛІМГЕ ҰСЫНЫСЫ\")\n",
        "    print(\"------------------------------------------\")\n",
        "\n",
        "    average = df[\"Нәтиже (%)\"].mean()\n",
