        "        st.warning(\"⚠️ Алдымен оқушының аты-жөнін енгізіңіз.\")\n",
        "\n",
        "    else:\n",
        "\n",
        "        unanswered = 0\n",
        "        correct_count = 0\n",
        "        wrong_questions = []\n",
        "\n",
        "        for i in range(12):\n",
        "\n",
        "            if answers[i] == \"-- Жауапты таңдаңыз --\":\n",
        "                unanswered += 1\n",
        "\n",
        "            elif answers[i] == tasks[i][2]:\n",
        "                correct_count += 1\n",
        "\n",
        "            else:\n",
        "                wrong_questions.append(i)\n",
        "\n",
        "        if unanswered > 0:\n",
        "\n",
        "            st.warning(\n",
        "                f\"⚠️ {unanswered} сұраққа жауап берілмеген. \"\n",
        "                \"Барлық сұраққа жауап беріңіз.\"\n",
        "            )\n",
        "\n",
        "        else:\n",
        "\n",
        "            wrong_count = 12 - correct_count\n",
        "            percentage = correct_count / 12 * 100\n",
        "\n",
        "            st.header(\"📊 Тест нәтижесі\")\n",
        "\n",
        "            st.write(f\"👤 Оқушы: **{student_name}**\")\n",
        "            st.write(f\"🎓 Сынып: **{grade}**\")\n",
        "            st.write(f\"📚 Тақырып: **{chapter}**\")\n",
        "\n",
        "            st.write(\n",
        "                f\"✅ Дұрыс жауап: **{correct_count} / 12**\"\n",
        "            )\n",
        "\n",
        "            st.write(\n",
        "                f\"❌ Қате жауап: **{wrong_count} / 12**\"\n",
        "            )\n",
        "\n",
        "            st.write(\n",
        "                f\"📈 Нәтиже: **{percentage:.1f}%**\"\n",
        "            )\n",
        "\n",
        "            # =================================================\n",
        "            # ДИАГРАММА\n",
        "            # =================================================\n",
        "\n",
        "            st.subheader(\"📊 Нәтиже диаграммасы\")\n",
        "\n",
        "            chart_data = {\n",
        "                \"Дұрыс жауап\": correct_count,\n",
        "                \"Қате жауап\": wrong_count\n",
        "            }\n",
        "\n",
        "            st.bar_chart(chart_data)\n",
        "\n",
        "            # =================================================\n",
        "            # AI ДЕҢГЕЙІ\n",
        "            # =================================================\n",
        "\n",
        "            if percentage >= 90:\n",
        "\n",
        "                level = \"🏆 MASTER\"\n",
        "                conclusion = (\n",
        "                    \"Өте жоғары деңгей! \"\n",
        "                    \"Тақырыпты өте жақсы меңгерген.\"\n",
        "                )\n",
        "\n",
        "            elif percentage >= 75:\n",
        "\n",
        "                level = \"🌟 EXPERT\"\n",
        "                conclusion = (\n",
        "                    \"Жақсы нәтиже! \"\n",
        "                    \"Білімі жеткілікті жоғары.\"\n",
        "                )\n",
        "\n",
        "            elif percentage >= 60:\n",
        "\n",
        "                level = \"👍 ADVANCED\"\n",
        "                conclusion = (\n",
        "                    \"Ортадан жоғары нәтиже. \"\n",
        "                    \"Кейбір сұрақтарды қайталау қажет.\"\n",
        "                )\n",
        "\n",
        "            elif percentage >= 40:\n",
        "\n",
        "                level = \"📚 BEGINNER\"\n",
        "                conclusion = (\n",
        "                    \"Негізгі білім бар. \"\n",
        "                    \"Қосымша жаттығу қажет.\"\n",
        "                )\n",
        "\n",
        "            else:\n",
        "\n",
        "                level = \"🔰 STARTER\"\n",
        "                conclusion = (\n",
        "                    \"Тақырыпты қайта қарап, \"\n",
        "                    \"қосымша тапсырмалар орындау қажет.\"\n",
        "                )\n",
        "\n",
        "            st.subheader(f\"🤖 AI деңгейі: {level}\")\n",
        "\n",
        "            st.info(\n",
        "                f\"🤖 AI қорытындысы: {conclusion}\"\n",
        "            )\n",
        "\n",
        "            # =================================================\n",
        "            # ҚАТЕ ЖАУАПТАРДЫ ТАЛДАУ\n",
        "            # =================================================\n",
        "\n",
        "            if wrong_questions:\n",
        "\n",
        "                st.subheader(\"🔍 AI қате жауаптарды талдау\")\n",
        "\n",
        "                st.write(\n",
        "                    \"Оқушы келесі сұрақтардан қате жіберді:\"\n",
        "                )\n",
        "\n",
        "                for i in wrong_questions:\n",
        "\n",
        "                    st.write(\n",
        "                        f\"❌ **{i + 1}-сұрақ** — \"\n",
        "                        f\"{tasks[i][0]}\"\n",
        "                    )\n",
        "\n",
        "                    st.write(\n",
        "                        f\"   Дұрыс жауап: **{tasks[i][2]}**\"\n",
        "                    )\n",
        "\n",
        "                # =============================================\n",
        "                # AI ЖЕКЕ ҰСЫНЫСЫ\n",
        "                # =============================================\n",
        "\n",
        "                st.subheader(\"🎯 AI жеке ұсынысы\")\n",
        "\n",
        "                if chapter.startswith(\"1.\"):\n",
        "                    recommendation = (\n",
        "                        \"Компьютер құрылғылары, RAM, SSD/HDD, \"\n",
        "                        \"Internet және желі тақырыптарын қайталаңыз.\"\n",
        "                    )\n",
        "\n",
        "                elif chapter.startswith(\"2.\"):\n",
        "                    recommendation = (\n",
        "                        \"Бит, байт, KB, MB, GB және ақпарат \"\n",
        "                        \"көлемін есептеу тақырыптарын қайталаңыз.\"\n",
        "                    )\n",
        "\n",
        "                elif chapter.startswith(\"3.\"):\n",
        "                    recommendation = (\n",
        "                        \"Python синтаксисі, айнымалылар, \"\n",
        "                        \"мәлімет типтері және негізгі функцияларды қайталаңыз.\"\n",
        "                    )\n",
        "\n",
        "                elif chapter.startswith(\"4.\"):\n",
        "                    recommendation = (\n",
        "                        \"Алгоритм түрлері мен блок-схема \"\n",
        "                        \"элементтерін қайталаңыз.\"\n",
        "                    )\n",
        "\n",
        "                elif chapter.startswith(\"5.\"):\n",
        "                    recommendation = (\n",
        "                        \"if, elif, else және салыстыру \"\n",
        "                        \"операторларын қайталаңыз.\"\n",
        "                    )\n",
        "\n",
        "                elif chapter.startswith(\"6.\"):\n",
        "                    recommendation = (\n",
        "                        \"while циклі, break, continue және \"\n",
        "                        \"циклдің тоқтау шарттарын қайталаңыз.\"\n",
        "                    )\n",
        "\n",
        "                elif chapter.startswith(\"7.\"):\n",
        "                    recommendation = (\n",
        "                        \"list, индекс, len(), append(), \"\n",
        "                        \"remove() және sort() әдістерін қайталаңыз.\"\n",
        "                    )\n",
        "\n",
        "                elif chapter.startswith(\"8.\"):\n",
        "                    recommendation = (\n",
        "                        \"def, параметр, return және \"\n",
        "                        \"функцияны шақыруды қайталаңыз.\"\n",
        "                    )\n",
        "\n",
        "                elif chapter.startswith(\"9.\"):\n",
        "                    recommendation = (\n",
        "                        \"str, индекс, len(), upper(), lower() \"\n",
        "                        \"және replace() әдістерін қайталаңыз.\"\n",
        "                    )\n",
        "\n",
        "                elif chapter.startswith(\"10.\"):\n",
        "                    recommendation = (\n",
        "                        \"dict, key, value, keys(), values(), \"\n",
        "                        \"items() және pop() әдістерін қайталаңыз.\"\n",
        "                    )\n",
        "\n",
        "                elif chapter.startswith(\"11.\"):\n",
        "                    recommendation = (\n",
        "                        \"open(), read(), write(), close() және \"\n",
        "                        \"файл режимдерін қайталаңыз.\"\n",
        "                    )\n",
        "\n",
        "                else:\n",
        "                    recommendation = (\n",
        "                        \"for циклі, range(), цикл айнымалысы \"\n",
        "                        \"және қайталау құрылымдарын қайталаңыз.\"\n",
        "                    )\n",
        "\n",
        "                st.warning(\n",
        "                    f\"📚 **Қайталау қажет:** {recommendation}\"\n",
        "                )\n",
        "\n",
        "                if percentage < 60:\n",
        "\n",
        "                    st.error(\n",
        "                        \"🤖 AI кеңесі: бұл тарауды қайта оқып, \"\n",
        "                        \"тестті қайта орындаңыз.\"\n",
        "                    )\n",
        "\n",
        "                elif percentage < 80:\n",
        "\n",
        "                    st.info(\n",
        "                        \"🤖 AI кеңесі: қате кеткен сұрақтарды \"\n",
        "                        \"қайталап, қосымша жаттығу орындаңыз.\"\n",
        "                    )\n",
        "\n",
        "                else:\n",
        "\n",
        "                    st.success(\n",
        "                        \"🤖 AI кеңесі: біліміңіз жақсы. \"\n",
        "                        \"Қиын сұрақтарды ғана қайталау жеткілікті.\"\n",
        "                    )\n",
        "\n",
        "            else:\n",
        "\n",
        "                st.success(\n",
        "                    \"🎯 Керемет! Барлық 12 сұраққа дұрыс жауап берілді!\"\n",
        "                )\n",
        "\n",
        "            st.success(\"🎉 Тест аяқталды!\")\n",
        "            st.success(\"🎉 Тест аяқталды!\")\n",
        "\n",
        "            # =========================================================\n",
        "            # 💾 НӘТИЖЕНІ САҚТАУ\n",
        "            # =========================================================\n",
        "\n",
        "            st.session_state.results.append({\n",
        "                \"Оқушы\": student_name,\n",
        "                \"Сынып\": grade,\n",
        "                \"Тақырып\": chapter,\n",
        "                \"Дұрыс жауап\": correct_count,\n",
        "                \"Қате жауап\": wrong_count,\n",
        "                \"Нәтиже (%)\": round(percentage, 1),\n",
        "                \"AI деңгейі\": level\n",
        "            })\n",
        "\n",
        "\n",
        "# =========================================================\n",
        "# 📋 БАРЛЫҚ НӘТИЖЕЛЕР\n",
        "# =========================================================\n",
        "\n",
        "if st.session_state.results:\n",
        "\n",
        "    st.divider()\n",
        "    st.subheader(\"📋 Оқушылар нәтижесі\")\n",
        "\n",
        "    st.dataframe(\n",
        "        st.session_state.results,\n",
        "        use_container_width=True\n",
        "    )\n",
        "\n",
        "\n",
        "# =========================================================\n",
        "# 💾 CSV ФАЙЛҒА ЖҮКТЕУ\n",
        "# =========================================================\n",
        "\n",
        "if st.session_state.results:\n",
        "\n",
        "    csv_output = io.StringIO()\n",
        "\n",
        "    csv_writer = csv.DictWriter(\n",
        "        csv_output,\n",
        "        fieldnames=st.session_state.results[0].keys()\n",
        "    )\n",
        "\n",
        "    csv_writer.writeheader()\n",
        "    csv_writer.writerows(st.session_state.results)\n",
        "\n",
        "    st.download_button(\n",
        "        \"💾 Барлық нәтижені жүктеу\",\n",
        "        csv_output.getvalue().encode(\"utf-8-sig\"),\n",
        "        file_name=\"okushy_natizheleri.csv\",\n",
        "        mime=\"text/csv\",\n",
        "        use_container_width=True\n",
        "    )"
